namespace MyApp.Evals.Tests;

/// <summary>
/// Returns a deterministic stub response for offline / CI runs.
/// Used when EVAL_USE_REAL_AGENT is unset.
/// </summary>
internal sealed class StubChatClient : IChatClient
{
    public Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var text = "This is a stub response for evaluation purposes. " +
                   "The coaching agent would normally provide interview feedback here. " +
                   "Set EVAL_USE_REAL_AGENT=1 to use the real model.";
        var response = new ChatResponse(new ChatMessage(ChatRole.Assistant, text))
        {
            ModelId = "stub",
            Usage = new UsageDetails { InputTokenCount = 10, OutputTokenCount = 30 },
        };
        return Task.FromResult(response);
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default) =>
        throw new NotSupportedException("Streaming not supported in stub tier.");

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose() { }
}

internal static class Wire
{
    public static IChatClient ResolveAgentClient() =>
        EvalEnv.UseRealAgent ? AgentChatClientFactory.Create() : new StubChatClient();

    public static IChatClient ResolveAgentClient(Dictionary<string, string> modelOverrides)
    {
        // Compare mode: override model via ChatOptions.ModelId
        var inner = ResolveAgentClient();
        if (modelOverrides.Count == 0) return inner;
        // For now return the same client; model assignment via ChatOptions at call site
        return inner;
    }

    public static IChatClient ResolveJudgeClient(IChatClient fallback)
    {
        var judgeDeploy = Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME");
        if (!string.IsNullOrEmpty(judgeDeploy))
        {
            // Separate judge deployment — build a dedicated client
            var builder = Host.CreateApplicationBuilder();
            builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);
            builder.Services.AddAzureOpenAIChatClient("chat", judgeDeploy);
            return builder.Build().Services.GetRequiredService<IChatClient>();
        }
        return fallback;
    }
}

