+    public static void WriteReports() => TelemetryStore.FlushTo(
+        Path.Combine(RepoRoot.Find(), ".copilot", "perf-reports", "evals",
+                     EvalEnv.ReportFolder));
+
+    private static decimal ComputeCost(ChatResponse response)
+    {
+        var pricesPath = Path.Combine(AppContext.BaseDirectory, "Telemetry", "prices.json");
+        var prices = JsonSerializer.Deserialize<Dictionary<string, PriceEntry>>(
+            File.ReadAllText(pricesPath), s_options) ?? new();
+
+        var model = response.ModelId ?? "unknown";
+        if (!prices.TryGetValue(model, out var entry)) return 0m;
+
+        var inTok = response.Usage?.InputTokenCount ?? 0;
+        var outTok = response.Usage?.OutputTokenCount ?? 0;
+        return (inTok / 1000m * entry.InputPer1k) + (outTok / 1000m * entry.OutputPer1k);
+    }
+}
+
+public sealed record TelemetryInput(string Agent, string Text);
+public sealed record PriceEntry(decimal InputPer1k, decimal OutputPer1k);
+public sealed record TelemetryRecord(string AgentName, string Model, int InputTokens, int OutputTokens, long LatencyMs, decimal CostUsd);
+
+internal static class TelemetryStore
+{
+    private static readonly List<TelemetryRecord> s_records = new();
+
+    public static void Record(TelemetryRecord r) { lock (s_records) s_records.Add(r); }
+
+    public static void FlushTo(string outDir)
+    {
+        Directory.CreateDirectory(outDir);
+        lock (s_records)
+        {
+            var json = JsonSerializer.Serialize(s_records, new JsonSerializerOptions { WriteIndented = true });
+            File.WriteAllText(Path.Combine(outDir, "telemetry.json"), json);
+
+            var md = new System.Text.StringBuilder();
+            md.AppendLine("| Agent | Model | In Tok | Out Tok | Latency (ms) | Cost ($) |");
+            md.AppendLine("|-------|-------|--------|---------|--------------|----------|");
+            foreach (var r in s_records)
+                md.AppendLine($"| {r.AgentName} | {r.Model} | {r.InputTokens} | {r.OutputTokens} | {r.LatencyMs} | {r.CostUsd:F6} |");
+            File.WriteAllText(Path.Combine(outDir, "telemetry.md"), md.ToString());
+        }
+    }
+}
